head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > setHolidayRef]<br/>Calendar 컴포넌트에 휴일로 표시할 날짜를 DataCollection 으로 설정합니다.",
    "validation" : [
        "ref(필수) 파라미터로 접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식의 String 으로 설정합니다.",
        "휴일 데이터는 'yyyyMMdd' 포맷으로 정의되어야 합니다.",
        "휴일 데이터를 '*MMdd' 포맷으로 정의 시 매해 같은 날짜가 휴일로 표시됩니다.",
        "설정값이 형식에 맞지 않거나 접근할 수 없는 DataCollection 이면 적용되지 않습니다.",
        "renderType=component 일때 휴일에 설정되는 'w2calendar_holiday' CSS 클래스가 표시됩니다.",
        "setHolidayRef() 메소드로 휴일 정보가 설정되면 setHoliday() 메소드로 설정된 휴일 정보는 무시됩니다.",
        "DataCollection 의 데이터가 변경되면 참조된 공휴일 데이터가 자동으로 갱신됩니다.",
        "removeHoliday() 메소드는 setHolidayRef() 메소드로 설정된 휴일 정보를 제거하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // renderType=component 고정 (w2calendar_holiday CSS 클래스 표시 조건)
    let properties = {
        renderType : "component"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList([]);

    // comp 생성 함수 호출 (createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시월: 2025-11)
    await $c.gcm.createBasicCalendar(cList, eList);
}



// setHolidayRef 호출 (선택된 케이스에 따라 분기)
// validation:
//  - ref(필수): 'data:[DataCollection ID].[Key 또는 Column ID]' 형식의 String
//  - 휴일 데이터는 'yyyyMMdd' 포맷, '*MMdd' 포맷 시 매년 반복
//  - 형식 미일치/접근 불가 DataCollection 이면 적용되지 않음
//  - renderType=component 일때 'w2calendar_holiday' CSS 클래스 적용
//  - setHolidayRef 가 설정되면 setHoliday() 정보는 무시
//  - DataCollection 변경 시 자동 갱신
//  - removeHoliday() 는 setHolidayRef 휴일 미제거
scwin.btn_setHolidayRef_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let callLog = "";

    if (caseId === '1') {
        // 케이스 1: DataList 컬럼 (yyyyMMdd) - "20251115", "20251120"
        target1.setHolidayRef("data:dlt_holidayref.label");
        callLog = "setHolidayRef('data:dlt_holidayref.label')";
    } else if (caseId === '3') {
        // 케이스 3: '*MMdd' 매년 반복 - "*1105" → 매해 11/05 휴일 표시
        target1.setHolidayRef("data:dlt_holidayref_yearly.label");
        callLog = "setHolidayRef('data:dlt_holidayref_yearly.label')";
    } else if (caseId === '4') {
        // 케이스 4: 접근 불가 DataCollection - 적용되지 않음
        target1.setHolidayRef("data:invalid.col1");
        callLog = "setHolidayRef('data:invalid.col1')";
    } else if (caseId === '5') {
        // 케이스 5: 형식 미일치 - 적용되지 않음
        target1.setHolidayRef("invalid:format");
        callLog = "setHolidayRef('invalid:format')";
    } else if (caseId === '6') {
        // 케이스 6: setHoliday + setHolidayRef → Ref 우선, setHoliday 무시
        target1.setHoliday("20251110");
        target1.setHolidayRef("data:dlt_holidayref.label");
        callLog = "setHoliday('20251110') + setHolidayRef('data:dlt_holidayref.label')";
    } else if (caseId === '7') {
        // 케이스 7: setHolidayRef 후 ref 대상 DataList 의 데이터 변경 → 자동 갱신
        // - 기존 row 의 label 값을 setCellData 로 변경하여 휴일이 새 날짜로 갱신되는지 확인
        target1.setHolidayRef("data:dlt_holidayref.label");
        dlt_holidayref.setCellData(0, "label", "20251128");
        callLog = "setHolidayRef('data:dlt_holidayref.label') + dlt_holidayref.setCellData(0,'label','20251128')";
    } else if (caseId === '8') {
        // 케이스 8: setHolidayRef + removeHoliday + 재갱신 → Ref 휴일이 재표시됨 (Ref 휴일 미제거 확인)
        // - removeHoliday() 직후에는 일시적으로 휴일이 사라지지만,
        //   calendar 재갱신(gotoCalendar 등) 시 holidayXpath()가 다시 호출되어 Ref 휴일이 복원됨
        target1.setHolidayRef("data:dlt_holidayref.label");
        target1.removeHoliday();
        target1.gotoCalendar("20251111");  // 재갱신 트리거 → Ref 휴일 복원
        callLog = "setHolidayRef + removeHoliday + gotoCalendar('20251111') 재갱신";
    }

    // 호출 후 휴일 셀 일자 + 첫 번째 휴일 셀의 className (w2calendar_holiday 클래스 적용 여부)
    let holidayCells = target1.render.querySelectorAll('.w2calendar_holiday');
    let holidayDays = [];
    for (var i = 0; i < holidayCells.length; i++) {
        holidayDays.push(holidayCells[i].textContent);
    }
    let firstClassName = holidayCells.length > 0 ? holidayCells[0].className : '(휴일 셀 없음)';

    wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + callLog);
    wf_body_bottom.getObj("scwin").setReturnValue("[호출 후 휴일 일자] " + holidayDays.join(','));
    wf_body_bottom.getObj("scwin").setReturnValue("[첫 휴일 셀 className] " + firstClassName);
};
